vocab => [
['Emoji grammar', 'n. 表情语法', 'The unwritten rules of when symbols belong: requests, celebrations, never refusals.'],
['Softener', 'n. 柔化剂', 'An emoji that lowers the temperature of a request by one notch.'],
['Stakes', 'n. 赌注', 'How much rides on the message; high stakes delete decoration.'],
['Waffle', 'n. 废话/裹脚布', 'Softness that buries the ask — the failure mode of over-politeness.'],
['Riff', 'v. 接梗', 'Extending the room\'s celebration with their vocabulary and emoji.'],
['Trust fall', 'n. 信任背摔', 'An unrequested risk taken on others\' behalf — what a GIF in #data-help is.'],
['Bare', 'adj. 裸的', 'Refusals and bad news arrive without decoration — by design.'],
],
grammar => [
['Emoji as modality', q{<em>"Can you send the file today? 🙂"</em> versus <em>"The file blocks the regulator submission — needed by 4 PM."</em> — the emoji functions as a <strong>modality marker</strong>: it downgrades the imperative\'s force by one notch. Grammar lesson: stakes and modality markers are inversely related — as stakes rise, markers must fall, or the message reads unserious.}, q{"Can you send the file today? 🙂" 对 "The file blocks the regulator submission — needed by 4 PM."——表情是一个<strong>语气标记</strong>：把祈使句的力度下调一档。语法课：赌注与语气标记成反比——赌注升高时标记必须退场，否则消息显得不严肃。}],
['Riff grammar: their noun, your verb', q{<em>"The retry counter earned its keep. 🎉"</em> — riffing takes <strong>the room\'s noun</strong> (the counter, from the retro) and <strong>adds your verb</strong> (earned its keep). Celebration replies that reuse the team\'s artifacts read as membership; generic "congrats!" reads as attendance.}, q{"The retry counter earned its keep. 🎉"——接梗取<strong>房间的名词</strong>（回顾会里的计数器）加<strong>你的动词</strong>（earned its keep）。复用团队产物的庆祝读起来像成员；泛泛的"congrats!"读起来像出席。}],
],
tips => [
q{<strong>Soften requests, never refusals.</strong> A smiley on a "no" is the manipulation tell — bad news goes bare, always.},
q{<strong>Stakes delete emoji.</strong> Routine asks earn a softener; regulator-blocking asks earn bare words with a deadline.},
q{<strong>Celebrate in the room\'s vocabulary.</strong> Reference the team\'s own artifacts and emoji — membership is performed in the reply thread.},
q{<strong>GIFs are channel-specific.</strong> #random hosts them; help channels and deploys do not. Know the geography of fun.},
q{<strong>When unsure, delete the emoji.</strong> Ambiguity in written tone never resolves in your favour — bare words are always survivable.},
],
practice => [
{ t => 'Emoji audit', p => 'Review your last ten chat messages. Mark each emoji: softener, celebration, decoration, or mistake. Count the mistakes.', a => q{The mistake category is where learning lives: an emoji on bad news, a grin on a deadline, a thumbs-up on a refusal. Most people find two or three — that is the dialect gap to close.} },
{ t => 'The stakes rewrite', p => 'Rewrite for rising stakes: (a) routine ask for a file, (b) the file blocks a demo tomorrow, (c) the file blocks a regulator submission at 4 PM.', a => q{(a) "Can you send the file today? 🙂" (b) "The file blocks tomorrow\'s demo — by end of day, please?" (c) "The file blocks the regulator submission — needed by 4 PM today." Watch the softener die as stakes rise.} },
{ t => 'The celebration riff', p => 'Your team posts "Zero rollbacks! 🎉". Write two riff replies: one crediting a team artifact, one crediting a person.', a => q{Model (a): "The retry counter earned its keep. 🎉" Model (b): "Priya\'s deploy checklist did its job again. 🎉" — their nouns, your verbs, the room\'s emoji. Generic congratulations are attendance; riffs are membership.} },
],
},
